function parseFieldPlan(value: any, duration: number, maxClips: number, message: string) {
  if (typeof value?.error === "string" && value.error.trim()) throw new Error(value.error.slice(0,1000));
  const fail = () => { throw new Error(message); };
  if (!value || typeof value.searchComplete !== "boolean" || !Array.isArray(value.clips) || value.clips.length > maxClips || typeof value.countReason !== "string") fail();
  const used: number[][] = [];
  const clips = value.clips.map((clip: any) => {
    if (![clip?.headline1,clip?.headline2,clip?.why].every(v=>typeof v === "string" && v.trim() && v.length <= 600) || !Array.isArray(clip.segments) || !clip.segments.length || clip.segments.length > 40) fail();
    const segments = clip.segments.map((range: any) => {
      if (!Array.isArray(range) || range.length !== 2 || !range.every((n: any)=>typeof n === "number" && Number.isFinite(n)) || range[0] < 0 || range[1] > duration || range[1]-range[0] < 0.5) fail();
      return [range[0],range[1]];
    });
    for (let i=0;i<segments.length;i++) {
      const [a,b] = segments[i];
      if ((i && a < segments[i-1][1]) || used.some(([x,y])=>a<y && b>x)) fail();
      used.push([a,b]);
    }
    if (!Array.isArray(clip.observations) || clip.observations.length < 2 || clip.observations.length > 120) fail();
    const observations = clip.observations.map((o: any) => {
      if (typeof o?.timeSeconds !== "number" || !Number.isFinite(o.timeSeconds) || typeof o.description !== "string" || !o.description.trim() || o.description.length > 1000 || !segments.some(([a,b]: number[])=>o.timeSeconds>=a && o.timeSeconds<b)) fail();
      return {timeSeconds:o.timeSeconds,description:o.description.trim()};
    });
    if (!segments.every(([a,b]: number[])=>observations.some((o: any)=>o.timeSeconds>=a && o.timeSeconds<b))) fail();
    return {headline1:clip.headline1.trim(),headline2:clip.headline2.trim(),why:clip.why.trim(),segments,observations,assessment:null,highlights:[]};
  });
  return {clips,recommendedCount:clips.length,countReason:value.countReason.slice(0,1000),searchComplete:value.searchComplete,fixes:[],captionOmissions:[]};
}

function fieldBuildOptions(job: any, tpl: any) {
  return {
    contentMode: fieldMode(job) ? "field" : "speech",
    fieldWindow: {top:tpl.layout.windowTop,bottom:tpl.layout.windowBottom},
    removeFillers: !fieldMode(job) && !!tpl.editing.removeFillers,
    removeSilences: !fieldMode(job) && !!tpl.editing.removeSilences,
  };
}

function ShortformClipsPanel({ sdk, context, ui, files }: any) {
  const lang = langOf(context);
  const S = merge(RADIO_STRINGS[lang] ?? RADIO_STRINGS.en, STRINGS[lang] ?? STRINGS.en);
  const projectId: string | null = context?.projectId ?? null;
  const store = React.useMemo(() => makeStore(files), [files]);
  const [tab, setTab] = React.useState<string>("make");
  const repository = React.useMemo(() => makeTemplateRepository(store), [store]);
  const [templates, setTemplates] = React.useState<any[]>([]);
  const [packs, setPacks] = React.useState<any[]>([]);
  const [packLink, setPackLink] = React.useState("");
  const [packDialogOpen, setPackDialogOpen] = React.useState(false);
  const [packBusy, setPackBusy] = React.useState(false);
  const [templateSaving, setTemplateSaving] = React.useState(false);
  const [templatesLoading, setTemplatesLoading] = React.useState(true);
  const templateLoadRevision = React.useRef(0);
  const [packMessage, setPackMessage] = React.useState("");
  const [packError, setPackError] = React.useState("");
  const packLock = React.useRef(false);
  const K = PACK_STRINGS[lang] || PACK_STRINGS.en;
  const F = FIELD_STRINGS[lang] || FIELD_STRINGS.en;
  const R=RESULT_STRINGS[lang]||RESULT_STRINGS.en;
  const O=OVERLAY_STRINGS[lang]||OVERLAY_STRINGS.en;
  const [visibleDraftId,setVisibleDraftId]=React.useState<string|null>(null);
  const [openingDraft,setOpeningDraft]=React.useState<string|null>(null);
  const openingLock=React.useRef(false);
  const [overlayTarget,setOverlayTarget]=React.useState<any>(null);
  const [overlayBusy,setOverlayBusy]=React.useState(false);
  const [overlayPending,setOverlayPending]=React.useState<boolean|null>(null);
  const [overlayLoading,setOverlayLoading]=React.useState(false);
  const [overlayRefresh,setOverlayRefresh]=React.useState(0);
  const [overlayMessage,setOverlayMessage]=React.useState("");
  const [overlayError,setOverlayError]=React.useState(false);
  const overlayLock=React.useRef(false);
  const overlayScopeKey=JSON.stringify([projectId,context.sequenceId]);
  const overlayScope=React.useRef({key:overlayScopeKey});
  if(overlayScope.current.key!==overlayScopeKey)overlayScope.current={key:overlayScopeKey};
  React.useEffect(()=>{setVisibleDraftId(null);setOverlayTarget(null);setOverlayPending(null);setOverlayMessage("");setOverlayError(false);},[projectId,context.sequenceId,overlayRefresh]);
  const [mode, setMode] = React.useState<string>("youtube");
  const [contentMode, setContentMode] = React.useState<string>("speech");
  const [url, setUrl] = React.useState<string>("");
  const [resources, setResources] = React.useState<any[]>([]);
  const [pick, setPick] = React.useState<string | null>(null);
  const [program, setProgram] = React.useState<string>("auto");
  const [platform, setPlatform] = React.useState<string>("tiktok");
  const [countMode, setCountMode] = React.useState<string>("auto");
  const [count, setCount] = React.useState<number>(4);
  const [note, setNote] = React.useState<string>("");
  const [busy, setBusy] = React.useState<boolean>(false);
  const [step, setStep] = React.useState<number>(-1);
  const [status, setStatus] = React.useState<string>("");
  const [error, setError] = React.useState<string>("");
  const [warn, setWarn] = React.useState<string>("");
  const [info, setInfo] = React.useState<any>(null);
  const [drafts, setDrafts] = React.useState<any[]>([]);
  const [jobs, setJobs] = React.useState<any[]>([]);
  const [resultJobs,setResultJobs]=React.useState<any[]>([]);
  const [resultSelection,setResultSelection]=React.useState("__latest__");
  const resultProject=React.useRef(projectId);
  resultProject.current=projectId;
  const [runInfo, setRunInfo] = React.useState<any>(null);
  const [now, setNow] = React.useState<number>(Date.now());
  const [sub, setSub] = React.useState<number>(0);
  const [cancelling, setCancelling] = React.useState<boolean>(false);
  const stepStarted = React.useRef<number>(Date.now());
  const resultsRef = React.useRef<HTMLDivElement>(null);
  const resultsRevision = React.useRef(0);
  const [tplSel, setTplSel] = React.useState<string>("");
  const [tplEdit, setTplEdit] = React.useState<any>(null);
  const [tplBase, setTplBase] = React.useState<string>("");
  const [tplSub, setTplSub] = React.useState<string>("look");

  // A run shows how long its current step has taken, so a slow AI step does not look stuck.
  React.useEffect(() => {
    stepStarted.current = Date.now();
    setNow(Date.now());
    setSub(0);
  }, [step]);
  React.useEffect(() => {
    if (!busy) return;
    window.scrollTo({ top: 0, behavior: "smooth" });
    const t = setInterval(() => setNow(Date.now()), 1000);
    return () => clearInterval(t);
  }, [busy]);

  // Resource ids are Project-scoped aliases; every script re-resolves a saved one by id and file name.
  const resolver = (resourceId: string, resourceName: string) =>
    `const project = selects.project(${JSON.stringify(projectId)}); const rows = await project.resources(); ` +
    `const res = rows.find((r: any) => r.resourceId === ${JSON.stringify(resourceId)} && (${JSON.stringify(!resourceName)} || r.name === ${JSON.stringify(resourceName)})) || rows.find((r: any) => r.name === ${JSON.stringify(resourceName)}) || rows.find((r: any) => r.resourceId === ${JSON.stringify(resourceId)}) || null; `;
  // The run in progress. Cancelling rejects its stop promise, which every host call of the run is raced against.
  const runRef = React.useRef<{ cancelled: boolean; stop: Promise<never>; cancel(): void } | null>(null);
  const guard = <T,>(p: Promise<T>): Promise<T> => {
    const run = runRef.current;
    if (!run) return p;
    if (run.cancelled) return Promise.reject(new RunCancelled());
    return Promise.race([p, run.stop]);
  };
  const script = async (code: string, summary: string, allowCommit = false) => {
    const r: any = await guard(sdk.runScript({ script: code, summary, allowCommit }));
    if (r.isError) throw Object.assign(new Error(scriptError(r.output)), { code: scriptCode(r.output) });
    return r.result;
  };
  // The same, not raced with the user's cancel: for cleaning up host jobs after the run has stopped.
  const scriptNow = async (code: string, summary: string, allowCommit = false) => {
    const r: any = await sdk.runScript({ script: code, summary, allowCommit });
    if (r.isError) throw Object.assign(new Error(scriptError(r.output)), { code: scriptCode(r.output) });
    return r.result;
  };
  const shell = async (command: string, summary: string, timeoutMs = 120000, cwd?: string) => {
    const cmd = IS_WIN ? "@echo off\r\n" + command.replace(/\r?\n/g, "\r\n") : command;
    const r: any = await guard(sdk.runShell({ summary, command: cmd, timeoutMs, maxOutputBytes: 48000, ...(cwd ? { cwd } : {}) }));
    return { ...r, stdout: String(r.stdout || ""), stderr: String(r.stderr || ""), output: String(r.output || "") };
  };

  async function ensureOverlayAsset(){
    const findCode=`const rows=await selects.project(${JSON.stringify(projectId)}).resources();return rows.find(x=>${JSON.stringify(TIKTOK_OVERLAY_ALIASES)}.includes(x.name))?.resourceId||null;`;
    const found=await script(findCode,"Find TikTok overlay image");if(found)return found;
    if(!files||!store.media)throw Error(S.noFileAccess);
    const path=store.join(store.media,TIKTOK_OVERLAY_ASSET_NAME);
    if(!(await store.exists(path)))await files.writeFile(path,fromBase64(TIKTOK_OVERLAY_PNG.split(',')[1]));
    const r=await script(`const p=selects.project(${JSON.stringify(projectId)});const rows=await p.resources();const found=rows.find(x=>${JSON.stringify(TIKTOK_OVERLAY_ALIASES)}.includes(x.name));if(found)return {id:found.resourceId};const r=await p.importFiles({paths:[${JSON.stringify(path)}]});return {id:r.addedResourceIds[0]||null};`,"Prepare TikTok overlay image",true);
    if(!r?.id)throw Error('\ud2f1\ud1a1 PNG\ub97c \ud504\ub85c\uc81d\ud2b8\uc5d0 \ucd94\uac00\ud558\uc9c0 \ubabb\ud588\uc2b5\ub2c8\ub2e4. / Could not prepare overlay image.');return r.id;
  }
  const overlayCall=async(payload:any,commit=false)=>{
    const r:any=await sdk.runScript({script:SCRIPT_OVERLAY.replace("const P:any=__P__;","const P:any="+JSON.stringify({projectId,requireVisible:true,...payload})+";"),summary:"Manage TikTok overlay",allowCommit:commit});
    if(r.isError)throw Error(scriptError(r.output));
    if(!r.result){if(commit)return {unconfirmed:true};throw Error(O.failed);}
    return r.result;
  };
  async function manageOverlay(action:string){
    if(overlayLock.current||busy||overlayLoading||!projectId||!overlayTarget)return;
    const scope=overlayScope.current;
    const isCurrent=()=>overlayScope.current===scope;
    overlayLock.current=true;setOverlayBusy(true);setOverlayPending(action==="add");setOverlayError(false);setOverlayMessage("");
    try{
      const current=await overlayCall({action:"inspect",sequenceId:overlayTarget.id});
      if(!isCurrent())return;
      if(current.id!==overlayTarget.id)throw Error(O.empty);
      if(action==="remove"){
        await overlayCall({action,sequenceId:current.id,signature:current.signature},true);
      }else{
        if(!isCurrent())return;
        const overlayResourceId=await ensureOverlayAsset();
        if(!isCurrent())return;
        await overlayCall({action,sequenceId:current.id,overlayResourceId},true);
      }
      if(!isCurrent())return;
      const after=await overlayCall({action:"inspect",sequenceId:current.id});
      if(!isCurrent())return;
      setOverlayTarget({id:after.id,name:after.name,count:after.count});
      if(action==="remove"){
        if(after.count!==0)throw Error(O.failed);
      }else{
        if(after.count!==1||after.legacy)throw Error(O.failed);
      }
    }catch(e:any){if(isCurrent()){setOverlayError(true);setOverlayMessage(String(e?.message||e));}}
    finally{overlayLock.current=false;setOverlayBusy(false);setOverlayPending(null);}
  }

  // Follow the visible Draft; stale reads must never replace the current target.
  React.useEffect(()=>{
    let live=true;
    const scope=overlayScope.current;
    const isCurrent=()=>live&&overlayScope.current===scope;
    if(!projectId||busy||overlayBusy){setOverlayLoading(false);return;}
    setOverlayLoading(true);
    (async()=>{
      try{
        const stateResult=await sdk.runScript({script:"return await selects.editor.state();",summary:"Check visible Draft",allowCommit:false});
        if(!isCurrent())return;
        if(stateResult.isError||!stateResult.result)throw Error(O.failed);
        const state=stateResult.result;
        if(state.projectId!==projectId||state.onScreenTab?.kind!=="draft"){
          setVisibleDraftId(null);setOverlayTarget(null);return;
        }
        setVisibleDraftId(state.onScreenTab.sequenceId);
        const current=await overlayCall({action:"inspect",sequenceId:state.onScreenTab.sequenceId});
        if(!isCurrent())return;
        setOverlayTarget({id:current.id,name:current.name,count:current.count});
      }catch(e:any){if(isCurrent()){setOverlayTarget(null);setOverlayError(true);setOverlayMessage(String(e?.message||e));}}
      finally{if(isCurrent())setOverlayLoading(false);}
    })();
    return ()=>{live=false;};
  },[projectId,context.sequenceId,busy,overlayBusy,overlayRefresh]);

  // ---- Templates: installed packs, user overrides and independent copies ----
  const loadTemplates = React.useCallback(async () => {
    const revision = ++templateLoadRevision.current;
    try {
      const result = await repository.load();
      if (revision !== templateLoadRevision.current) return null;
      setTemplates(result.templates);
      setPacks(result.packs);
      setPackError(result.errors.join("\n"));
      setTplSel(id => result.templates.some(t => t.id === id) ? id : result.templates[0]?.id || "");
      setProgram(id => id === "auto" || result.templates.some(t => t.id === id) ? id : "auto");
      return result.templates;
    } catch (e: any) {
      if (revision === templateLoadRevision.current) setPackError(String(e?.message || e));
      return null;
    } finally { if (revision === templateLoadRevision.current) setTemplatesLoading(false); }
  }, [repository]);
  const templateDirty = !!tplEdit && JSON.stringify(tplEdit) !== tplBase;
  async function installPack(link = packLink, requestId?: string) {
    if (!link.trim() || packLock.current || busy || templateDirty || templateSaving) return;
    packLock.current = true;
    setPackBusy(true); setPackError(""); setPackMessage("");
    try {
      const installed = await repository.install(link.trim(), true);
      setPackLink("");
      const loaded = await loadTemplates();
      if (requestId) {
        const first = loaded?.find(t => t.id.startsWith(installed.id + "/"));
        if (first) { setTplSel(first.id); setProgram(first.id); }
      }
      setPackMessage(K.installed + " " + (installed.names?.[lang] || installed.name));
      setPackDialogOpen(false);
    } catch (e: any) { setPackError(K.failed + " " + (K[e?.code] || String(e?.message || e))); }
    finally {
      packLock.current = false; setPackBusy(false);
      if (requestId) sdk.finishTemplatePackInstall?.(requestId);
    }
  }
  const attemptedPack = React.useRef<string | null>(null);
  React.useEffect(() => {
    const request = context?.templatePack;
    if (!request || attemptedPack.current === request.requestId || !files || templatesLoading || busy || packBusy || templateDirty || templateSaving) return;
    attemptedPack.current = request.requestId;
    setTab("templates"); setPackLink(request.url); setPackDialogOpen(true);
    void installPack(request.url, request.requestId);
  }, [context?.templatePack?.requestId, files, templatesLoading, busy, packBusy, templateDirty, templateSaving]);
  React.useEffect(() => {
    loadTemplates();
  }, [loadTemplates]);

  // ---- Saved progress: each step is written to disk so a closed or reloaded panel can resume ----
  const saveJob = async (job: any) => store.put("jobs", job.id, job);
  const loadJobs = React.useCallback(async () => {
    if (!projectId) return;
    try {
      const since = Date.now() - 14 * 24 * 3600 * 1000;
      const list = (await store.list("jobs"))
        .filter((j: any) => j && j.projectId === projectId && !j.done && !j.dismissed && Date.parse(j.updated || j.created || "") > since)
        .sort((a: any, b: any) => String(b.updated).localeCompare(String(a.updated)));
      setJobs(list);
    } catch (e) {}
  }, [projectId, store]);
  React.useEffect(() => {
    loadJobs();
  }, [loadJobs]);

  // Reopening the panel restores saved results without rerunning generation or editing Drafts.
  React.useEffect(() => {
    const revision = ++resultsRevision.current;
    let live = true;
    setResultJobs([]);setResultSelection("__latest__");
    setDrafts([]); setInfo(null); setWarn(""); setStatus(""); setStep(-1);
    if (projectId) store.list("jobs").then((rows: any[]) => {
      if (!live) return;
      setResultJobs(current=>savedDraftResults([...rows.filter(j=>!current.some(c=>c.id===j.id)),...current],projectId));
      if (resultsRevision.current !== revision || runRef.current) return;
      const job = latestDraftResult(rows, projectId);
      if (!job) return;
      setDrafts(job.built.filter(Boolean));
      setInfo({ key: job.key, why: job.why, recommended: job.choice?.recommendedCount, countReason: job.choice?.countReason });
      setWarn(job.resultWarning || "");
      setStep(5);
    }).catch(() => {if(live && resultsRevision.current===revision)setError(R.historyError);});
    return () => { live = false; };
  }, [projectId, store]);

  const loadResources = React.useCallback(async () => {
    if (!projectId) return;
    try {
      const rows = await script(
        `return (await selects.project(${JSON.stringify(projectId)}).resources()).filter((r: any) => r.type === "Video").map((r: any) => ({ id: r.resourceId, name: r.name, analyzed: r.hasAnalysis, transcribed: r.hasTranscription, status: r.status, sec: Math.round(r.durationSeconds ?? 0) }));`,
        "List project videos"
      );
      setResources(rows || []);
    } catch (e: any) {
      if (!(e instanceof RunCancelled)) setError(String(e?.message || e));
    }
  }, [projectId]);
  React.useEffect(() => {
    loadResources();
  }, [loadResources]);
  React.useEffect(() => {
    if (typeof sdk?.on !== "function") return;
    const off = sdk.on("resourcesChanged", () => loadResources());
    return typeof off === "function" ? off : undefined;
  }, [projectId]);
  React.useEffect(() => {
    const eligible = resources;
    if (eligible.length === 1) {
      if (pick !== eligible[0].id) setPick(eligible[0].id);
    } else if (pick && !eligible.some((r) => r.id === pick)) {
      setPick(null);
    }
  }, [resources]);

  // ---- Host programs: yt-dlp (downloaded into the app's folder when missing) and ffmpeg ----
  async function dataPaths() {
    if (store.root) return { root: store.root, media: store.media, bin: store.bin, join: store.join };
    if (IS_WIN) throw new Error(S.noFileAccess);
    const home = (await shell(`printf %s "$HOME"`, "Find home folder")).stdout.trim();
    const root = `${home}/.selects/plugin-data/${APP_ID}`;
    return { root, media: `${root}/media`, bin: `${root}/bin`, join: (...p: string[]) => p.join("/") };
  }

  async function findTools(): Promise<{ ytdlp: string | null; ffmpeg: string | null }> {
    const P = await dataPaths();
    const own = P.join(P.bin, IS_WIN ? "yt-dlp.exe" : "yt-dlp");
    let cmd: string;
    if (IS_WIN) {
      const local = store.fs ? store.join(store.fs.homedir(), "AppData", "Local", "Programs") : "";
      const bundled = local ? ["Selects", "Selects Staging"].map((a) => store.join(local, a, "resources", "app.asar.unpacked", "dist", "bin", "ffmpeg.exe")) : [];
      cmd = [
        `if exist ${wq(own)} echo Y=OWN`,
        ...bundled.map((f, i) => `if exist ${wq(f)} echo F=BUNDLED${i}`),
        `for /f "delims=" %%i in ('where yt-dlp.exe 2^>nul') do echo Y=%%i`,
        `for /f "delims=" %%i in ('where ffmpeg.exe 2^>nul') do echo F=%%i`,
        `exit /b 0`,
      ].join("\n");
    } else {
      const apps = ["Selects", "Selects Staging", "Selects Delta"].map((a) => pq(`/Applications/${a}.app/Contents/Resources/app.asar.unpacked/dist/bin/ffmpeg`)).join(" ");
      cmd =
        `for p in ${pq(own)} "$(command -v yt-dlp 2>/dev/null)" "$HOME/.local/bin/yt-dlp" /opt/homebrew/bin/yt-dlp /usr/local/bin/yt-dlp; do [ -n "$p" ] && [ -x "$p" ] && echo "Y=$p"; done; ` +
        `for p in "$(command -v ffmpeg 2>/dev/null)" /opt/homebrew/bin/ffmpeg /usr/local/bin/ffmpeg ${apps}; do [ -n "$p" ] && [ -x "$p" ] && echo "F=$p"; done; true`;
    }
    const r = await shell(cmd, "Find yt-dlp and ffmpeg", 60000);
    const lines = r.stdout.split(/\r?\n/).map((l: string) => l.trim());
    const first = (p: string) => {
      const l = lines.find((x: string) => x.startsWith(p + "="));
      return l ? l.slice(p.length + 1).trim() : null;
    };
    const y = first("Y");
    const f = first("F");
    const bundledPath = (i: number) => store.join(store.fs.homedir(), "AppData", "Local", "Programs", ["Selects", "Selects Staging"][i], "resources", "app.asar.unpacked", "dist", "bin", "ffmpeg.exe");
    const ff = f && /^BUNDLED\d$/.test(f) ? bundledPath(Number(f.slice(7))) : f;
    return { ytdlp: y === "OWN" ? own : y, ffmpeg: ff };
  }

  async function installYtdlp(): Promise<string> {
    const P = await dataPaths();
    const target = P.join(P.bin, IS_WIN ? "yt-dlp.exe" : "yt-dlp");
    const part = target + ".part";
    const cmd = IS_WIN
      ? [
          `if not exist ${wq(P.bin)} mkdir ${wq(P.bin)}`,
          `curl.exe -fsSL --retry 3 -o ${wq(part)} ${wq(YTDLP_URL)} || exit /b 1`,
          `move /y ${wq(part)} ${wq(target)} >nul || exit /b 1`,
          `${wq(target)} --version`,
        ].join("\n")
      : `mkdir -p ${pq(P.bin)} && curl -fsSL --retry 3 -o ${pq(part)} ${pq(YTDLP_URL)} && mv -f ${pq(part)} ${pq(target)} && chmod +x ${pq(target)} && ${pq(target)} --version`;
    const r = await shell(cmd, "Download yt-dlp", 290000);
    if (r.exitCode === 0 && /\d{4}\.\d{2}\.\d{2}/.test(r.stdout)) return target;
    // curl can be missing or blocked; Selects' own downloader is the fallback.
    const fs = store.fs;
    if (fs && typeof fs.downloadFile === "function") {
      await store.ensure(P.bin);
      await fs.downloadFile(YTDLP_URL, target);
      const v = await shell(IS_WIN ? `${wq(target)} --version` : `chmod +x ${pq(target)} && ${pq(target)} --version`, "Check yt-dlp", 120000);
      if (v.exitCode === 0) return target;
    }
    throw new Error(S.ytdlpFailed + shortError(r.stderr || r.output || ""));
  }

  // ---- Step 1: get a project resource for the source ----
  async function prepareFromYoutube(link: string): Promise<{ resourceId: string; resourceName: string; title: string }> {
    setStatus(S.preparingSource);
    const P = await dataPaths();
    let tools = await findTools();
    let refreshed = false;
    if (!tools.ytdlp) {
      tools = { ...tools, ytdlp: await installYtdlp() };
      refreshed = true;
    }
    // A failing yt-dlp is most often an old one, since YouTube changes break it: get the latest once and retry.
    // When the update itself fails, the original failure is the one worth showing.
    const refreshYtdlp = async () => {
      if (refreshed) return false;
      refreshed = true;
      setStatus(S.preparingSource);
      try {
        tools = { ...tools, ytdlp: await installYtdlp() };
        return true;
      } catch {
        return false;
      }
    };
    if (store.fs) await store.ensure(P.media);
    else await shell(`mkdir -p ${pq(P.media)}`, "Create download folder");
    const readDetails = () =>
      shell(`${qa(tools.ytdlp!)} --no-warnings --encoding utf-8 --skip-download --no-playlist --print id --print title ${qa(link)}`, "Read video details", 120000);
    const detailsOk = (r: any) => r.exitCode === 0 && r.stdout.trim().split(/\r?\n/).length >= 2;
    let metaR = await readDetails();
    if (!detailsOk(metaR) && (await refreshYtdlp())) metaR = await readDetails();
    const lines = metaR.stdout.trim().split(/\r?\n/);
    if (!detailsOk(metaR)) {
      console.warn("[shortform-clips] read link", (metaR.stderr || metaR.output || "").slice(-2000));
      throw new Error(S.readLinkFailed + shortError(metaR.stderr || metaR.output));
    }
    const vid = lines[lines.length - 2].trim();
    const title = lines[lines.length - 1].trim();
    const file = P.join(P.media, `${vid}.mp4`);
    const fmt = tools.ffmpeg ? "137+140/bv*[height<=1080][vcodec^=avc1]+ba[ext=m4a]/b[height<=1080]" : "b[ext=mp4][height<=1080]/b";
    if (!tools.ffmpeg) setWarn(S.noFfmpeg);
    const base = () =>
      `${qa(tools.ytdlp!)} --no-warnings --no-progress --encoding utf-8 --no-playlist -N 4 -f ${qa(fmt)} --merge-output-format mp4 ` +
      (tools.ffmpeg ? `--ffmpeg-location ${qa(tools.ffmpeg)} ` : "") +
      `-o ${qa(P.join(P.media, "%(id)s.%(ext)s"))} ${qa(link)}`;
    const have = async () =>
      store.fs ? store.exists(file) : (await shell(`[ -s ${pq(file)} ] && echo HAVE`, "Check download")).stdout.includes("HAVE");
    let ok = await have();
    // Chrome's cookies are read only when YouTube wants a signed-in viewer, since reading them can raise a
    // macOS Keychain prompt.
    let withCookies = false;
    for (let attempt = 0; !ok && attempt < 8; attempt++) {
      setStatus(S.downloading(attempt + 1));
      const cookies = withCookies && !IS_WIN ? " --cookies-from-browser chrome" : "";
      const r = await shell(base() + cookies, "Download the YouTube video", 290000);
      ok = await have();
      const out = r.stderr || r.output || "";
      if (!ok && out) console.warn("[shortform-clips] download attempt", attempt + 1, out.slice(-2000));
      if (!ok && /sign in|not a bot|confirm your age|age-restricted|login required|members-only|cookies/i.test(out)) withCookies = true;
      if (!ok && !r.timedOut && r.exitCode !== 0 && (await refreshYtdlp())) continue;
      if (!ok && !r.timedOut && r.exitCode !== 0 && attempt >= 3) throw new Error(S.downloadFailed + shortError(out));
    }
    if (!ok) throw new Error(S.downloadUnfinished);
    const existing = await script(
      `const r = (await selects.project(${JSON.stringify(projectId)}).resources()).find((r: any) => String(r.name).includes(${JSON.stringify(vid)})); return r ? { id: r.resourceId, name: r.name } : null;`,
      "Look for an earlier import"
    );
    if (existing?.id) return { resourceId: existing.id, resourceName: existing.name, title };
    const imp = await script(
      `const p = selects.project(${JSON.stringify(projectId)}); const imp = await p.importFiles({ paths: [${JSON.stringify(file)}] }); const id = imp?.addedResourceIds?.[0]; const r = id ? (await p.resources()).find((x: any) => x.resourceId === id) : null; return r ? { id, name: r.name } : null;`,
      "Import the video",
      true
    );
    if (!imp?.id) throw new Error(S.importFailed);
    return { resourceId: imp.id, resourceName: imp.name, title };
  }

  // ---- Step 2: speech needs a transcript; field footage needs visual analysis ----
  async function ensureTranscriptReady(resourceId: string, resourceName: string, requireVisual = false, waitingLabel = S.waitingAnalysis) {
    // The analysis run's own estimate and progress, so the wait shows how far it has got.
    const st = async () =>
      script(
        resolver(resourceId, resourceName) +
          `if (!res) throw new Error("The source video is no longer in this project."); const w = (await project.workflows({ type: "project:analyze-resource" })).find((x) => x.resourceId === res.resourceId && (x.status === "running" || x.status === "queued")); ` +
          `return { status: res.status, ready: res.hasAnalysis === true || (${!requireVisual} && res.hasTranscription === true), wf: w ? { startedAt: w.startedAt, est: w.estimatedDurationMs ?? null, progress: w.progress ?? null } : null };`,
        "Check analysis status"
      );
    let s = await st();
    if (s?.ready) return;
    if (s && !s.wf && ["pending", "samplingFailed", "analyzingFailed"].includes(s.status)) {
      // Selects asks the user to approve the credits in its own window and closes that request when this
      // script's 30 seconds run out. An unanswered or declined request comes back as a failed script.
      setStatus(S.confirmCredits);
      let begun: any = null;
      try {
        begun = await script(
          // `@speaker-profiling off` above opens that request with speaker profiling off: clips need words and
          // speaker ids, not speaker profiles.
          resolver(resourceId, resourceName) + `if (!res) throw new Error("The source video is no longer in this project."); return await project.startAnalysis({ resourceIds: [res.resourceId] });`,
          "Analyze the source video",
          true
        );
      } catch (e: any) {
        if (/Analysis canceled by user|confirmation deadline/i.test(String(e?.message || e))) throw new Error(S.confirmMissed);
        throw e;
      }
      if (begun?.cancelled) throw new Error(S.confirmMissed);
    }
    setStatus(waitingLabel);
    const t0 = Date.now();
    while (Date.now() - t0 < 45 * 60 * 1000) {
      await guard(sleep(10000));
      s = await st();
      if (s?.ready) return;
      if (s && /Failed$/.test(s.status)) throw new Error(S.analysisFailed(s.status));
      const w = s?.wf;
      if (w) {
        const ran = w.startedAt ? Date.now() - w.startedAt : 0;
        const frac = w.progress != null ? w.progress : w.est ? ran / w.est : null;
        if (frac != null) setSub(Math.max(0, Math.min(0.95, frac)));
        setStatus(waitingLabel);
      }
    }
    throw new Error(S.analysisSlow);
  }

  async function readTranscript(resourceId: string, resourceName: string) {
    const lines: any[] = [];
    let duration = 0;
    for (let off = 0; off < 5000; off += 250) {
      const r = await script(SCRIPT_TRANSCRIPT.replace("const P: any = __P__;", "const P: any = " + JSON.stringify({ projectId, resourceId, resourceName, offset: off, limit: 250 }) + ";"), "Read the transcript");
      duration = r.duration;
      lines.push(...r.lines);
      if (off + 250 >= r.total) break;
    }
    return { lines, duration };
  }

  // ---- Step 3: identify the program ----
  async function identify(title: string, lines: any[], list: any[]) {
    const head = lines.slice(0, 120).map((l) => l[2]).join(" ");
    const all = lines.map((l) => l[2]).join(" ");
    const byTitle = scoreProgram(title, list);
    if (byTitle) return { key: byTitle, why: `${S.whyTitle}: ${title}` };
    const byText = scoreProgram(head + " " + all.slice(0, 20000), list);
    if (byText) return { key: byText, why: S.whyTranscript };
    const prompt =
      `\uc774 \uc720\ud29c\ube0c \uc601\uc0c1\uc774 \uc5b4\ub290 \ud504\ub85c\uadf8\ub7a8\uc778\uc9c0 \ud310\ubcc4\ud558\ub77c. \ud6c4\ubcf4: ${list.map((t) => `${t.id}=${nameOf(t, "ko")}(${t.detect?.host || ""})`).join(", ")}. ` +
      `\ud574\ub2f9 \uc5c6\uc73c\uba74 "none". \ud544\uc694\ud558\uba74 \ud504\ub85c\uc81d\ud2b8 \ub3c4\uad6c\ub85c \uc774 \uc601\uc0c1(resource)\uc758 \ud654\uba74\uc744 \ud655\uc778\ud574 \uc88c\uc0c1\ub2e8/\uc6b0\uc0c1\ub2e8 \ub85c\uace0\ub97c \ubd10\ub3c4 \ub41c\ub2e4. \ud3b8\uc9d1\uc740 \ud558\uc9c0 \ub9c8\ub77c.\n` +
      `\uc81c\ubaa9/\ud30c\uc77c\uba85: ${title}\n\uc55e\ubd80\ubd84 \uc804\uc0ac: ${head.slice(0, 4000)}\n` +
      `JSON\ub9cc \ub2f5\ud558\ub77c: {"program": "<key or none>", "reason": "<\ud55c \ubb38\uc7a5>"}`;
    const r: any = await guard(sdk.askAI({ prompt, timeoutMs: 180000 }));
    const j = extractJson(r.text, S);
    if (!j.program || !list.some((t) => t.id === j.program)) return { key: null, why: j.reason || "" };
    return { key: j.program, why: `${S.whyAI}: ${j.reason || ""}` };
  }

  async function reframeClips(clips: any[], job: any, tpl: any, note: (entry: any) => void, saveClip: () => Promise<void>) {
    const L = tpl.layout;
    const windowW = 1080 / ((L.windowBottom - L.windowTop) / (L.sourceBottom - L.sourceTop));
    const inset = Number(L.edgeInset) || 0;
    const nm = JSON.stringify(job.resourceName || "");
    const rid = JSON.stringify(job.resourceId);
    const pid = JSON.stringify(projectId);
    const res =
      `const p = selects.project(${pid}); const rows = await p.resources(); ` +
      `const hit = rows.find((r: any) => r.resourceId === ${rid} && r.name === ${nm}) || rows.find((r: any) => r.name === ${nm}) || rows.find((r: any) => r.resourceId === ${rid}); ` +
      `if (!hit) throw new Error("The source video is no longer in this project."); const RID = hit.resourceId; `;
    const src = await script(res + SCRIPT_SOURCE_READER + `const { meta: m } = await readClipSource(p, RID); if (!m.frameSize?.width) throw new Error("Source frame size is unavailable."); return { fps: m.fps, duration: m.durationSeconds, W: m.frameSize.width };`, "Read the source");
    const fps = Number(src.fps) || 30;

    // One face job, polled until it ends (settleFaceJob). Jobs run one at a time: the runtime can crash when two
    // overlap, so a job that takes too long is cancelled, and its end awaited, before anything else is sent.
    async function faceJob(i: number, level: number, a: number, b: number, step: number): Promise<{ samples: any[]; W: number; H: number }> {
      const key = JSON.stringify(`${APP_ID}:${job.id}:${i}:v3:${level}:${keyHash(JSON.stringify({ task: "faces.detect", a, b, step }))}`);
      const t0 = Date.now();
      const entry: any = { clip: i, level, range: [a, b], step, key: JSON.parse(key) };
      try {
        let wfId = "";
        const settled = await settleFaceJob({
          submit: async () => {
            const got = await script(
              res + `const h = await selects.ai.submit({ runtimeId: "${AI_RUNTIME}", requestKey: ${key}, projectId: ${pid}, resourceId: RID, sourceRange: { startSeconds: ${a}, endSeconds: ${b} }, task: "faces.detect", options: { sampleEverySeconds: ${step} } }); return { wf: h.workflowId };`,
              "Find faces",
              true
            );
            wfId = entry.wf = got.wf;
            return got;
          },
          status: (cancel) =>
            script(`const j = selects.ai.job(${JSON.stringify(wfId)}, ${pid}); ${cancel ? "await j.cancel(); " : ""}const s = await j.status(); return { status: s.status, code: s.lastErrorCode || "", error: s.lastErrorMessage || "" };`, cancel ? "Stop face finding" : "Check face finding", cancel),
          wait: (ms) => guard(sleep(ms)),
          // Generous: a 60 s window takes well under a minute on a Mac.
          deadline: t0 + (120 + (b - a) * 5) * 1000,
          now: () => Date.now(),
          stop: (e) => e instanceof RunCancelled,
        });
        const wf = JSON.stringify(settled.wf);
        const s = settled.status;
        entry.status = s.status;
        if (s.status !== "succeeded") throw Object.assign(new Error(s.error || s.status), { code: s.code });
        // Faces are read a page at a time to stay under the script result size.
        const samples: any[] = [];
        let W = src.W, H = 1080;
        for (let off = 0; ; off += 400) {
          const page = await script(
            `const h = selects.ai.job(${wf}, ${pid}); const r = await h.result(); const j: any = await selects.ai.readJSON(r.files.detections, ${pid}); ` +
              `const q = (x: number) => Math.round(x); const all = j.samples; ` +
              `return { W: j.frameSize.width, H: j.frameSize.height, total: all.length, samples: all.slice(${off}, ${off + 400}).map((s: any) => [Math.round(s.sourceTimeSeconds * 1000) / 1000, s.faces.map((f: any) => { const w = f.box.xmax - f.box.xmin, hh = f.box.ymax - f.box.ymin; return [q((f.box.xmin + f.box.xmax) / 2), q(w), q(hh), q(((f.landmarks[3].y + f.landmarks[4].y) / 2 - f.landmarks[2].y) / Math.max(1, hh) * 1000), q((f.box.ymin + f.box.ymax) / 2)]; })]) };`,
            "Read faces"
          );
          W = page.W || W;
          H = page.H || H;
          samples.push(...page.samples);
          if (off + 400 >= page.total) break;
        }
        entry.samples = samples.length;
        return { samples, W, H };
      } catch (e: any) {
        if (e instanceof RunCancelled) throw e;
        entry.status = entry.status || "error";
        entry.code = e?.code || "";
        entry.error = String(e?.message || e).slice(0, 200);
        // The key, range and step above are what a later run needs to recover this job.
        if (e?.unsettled) entry.unsettled = true;
        throw e;
      } finally {
        entry.seconds = Math.round((Date.now() - t0) / 100) / 10;
        note(entry);
      }
    }

    // All faces for a list of ranges. A window whose result is too large (a crowded picture) is searched again
    // in halves.
    async function findFaces(i: number, level: number, ranges: number[][], step: number) {
      const samples: any[] = [];
      let W = src.W, H = 1080;
      const search = async (a: number, b: number) => {
        try {
          const got = await faceJob(i, level, a, b, step);
          W = got.W;
          H = got.H;
          for (const s of got.samples) if (!samples.length || s[0] > samples[samples.length - 1][0]) samples.push(s);
        } catch (e: any) {
          if (e instanceof RunCancelled || e?.code !== "AI_ARTIFACT_TOO_LARGE" || b - a < 10) throw e;
          const mid = Math.round(((a + b) / 2) * 1000) / 1000;
          await search(a, mid);
          await search(mid, b);
        }
      };
      for (const [a, b] of ranges) for (const [wa, wb] of faceWindows(a, b, step, fps)) await search(wa, wb);
      return { samples, W, H };
    }

    // The picture check, one AI call per clip with two sheets (at most about a minute; on any failure the face
    // numbers above stand). The mouth landmarks are noisy (a microphone, heads bent over notes) and know nothing of
    // the set, so the picture itself is looked at:
    // 1. Who talks: the clip is cut into stretches of a few seconds along the sentences; for each stretch every
    //    face is shown four times, close up, in time order. The face whose mouth keeps changing talks.
    // 2. How wide: for every face, its close-up alternatives cut from one frame as the window will show them; the
    //    widest that shows the face whole and nobody else's body and no set seam at the edges wins.
    // askAI runs a full agent turn with the project's tools; the prompt asks it to answer from the images alone, but
    // nothing enforces that.
    async function pictureCheck(i: number, c: any, log: any, srcH: number, samples: any[]) {
      const t0 = Date.now();
      const faces = (log.faces || []).filter((f: any) => f.w >= Math.max(...log.faces.map((g: any) => g.w)) * 0.5).sort((a: any, b: any) => a.x - b.x).slice(0, 5);
      if (!faces.length) return null;
      const inClip = (u: any) => c.segments.map((g: number[]) => [Math.max(u.start, g[0]), Math.min(u.end, g[1])]).filter((r: number[]) => r[1] - r[0] > 0.5);
      const pieces: any[] = [];
      for (const u of log.units || []) for (const [a, b] of inClip(u)) pieces.push({ start: a, end: b, spk: u.spk, x: u.face, y: u.faceY });
      let chunks: any[] = [];
      for (let len = 6; len <= 48; len *= 2) {
        chunks = [];
        for (const p of pieces) {
          const last = chunks[chunks.length - 1];
          if (last && last.spk === p.spk && Math.abs(p.start - last.end) < 1 && p.end - last.start <= len) last.end = p.end;
          else chunks.push({ ...p });
        }
        if (chunks.length <= 10) break;
      }
      chunks = chunks.filter((k: any) => k.end - k.start >= 0.8).slice(0, 10);
      if (!chunks.length) return null;
      try {
        const where = await script(
          res +
            // A large project lists its files per folder (as readClipSource handles).
            `const e = await selects.files.environment(); const sf: any = await p.sourceFiles(); const all: any[] = []; ` +
            `const walk = (n: any[]) => { for (const x of n || []) { if (x.type === "dir") walk(x.children); else all.push(x); } }; ` +
            `if ("fileTree" in sf) walk(sf.fileTree); else for (const fo of sf.folders || []) { const d: any = await p.sourceFiles({ folder: fo.name }); if ("fileTree" in d) walk(d.fileTree); if (all.some((x: any) => x.resourceId === RID)) break; } ` +
            `const f = all.find((x: any) => x.resourceId === RID); return { path: f ? f.path : null, tmp: e.tempDirectory };`,
          "Find the source file"
        );
        if (!where?.path) throw new Error("The source file has no path on this computer.");
        // A folder of its own for each attempt, so a job left over from an earlier run can never write into it.
        const dir = `${where.tmp}/shortform-clips-frames/${job.id}-${i}-${Date.now().toString(36)}`;
        // A band across all faces at full resolution for the close-ups, a whole frame per face for the crops.
        const y0 = Math.max(0, Math.round(Math.min(...faces.map((f: any) => f.cy - f.w * 1.3)))), y1 = Math.min(srcH, Math.round(Math.max(...faces.map((f: any) => f.cy + f.w * 1.3))));
        const bandTimes: number[] = [];
        for (const k of chunks) for (let n = 0; n < 4; n++) bandTimes.push(Math.round((k.start + 0.2 + ((k.end - k.start - 0.4) * (n + 0.5)) / 4) * 100) / 100);
        const faceTimes = faces.map((f: any) => {
          const mine = chunks.filter((k: any) => Math.hypot(k.x - f.x, (k.y ?? f.cy) - f.cy) < 150).sort((a: any, b: any) => b.end - b.start - (a.end - a.start))[0] || chunks[0];
          return Math.round(((mine.start + mine.end) / 2) * 100) / 100;
        });
        const args: string[] = ["-y", "-v", "error"];
        const outs: string[] = [];
        [...bandTimes, ...faceTimes].forEach((tt) => args.push("-ss", String(tt), "-i", where.path));
        bandTimes.forEach((tt, k) => { outs.push(`${dir}/b${k}.jpg`); args.push("-map", `${k}:v:0`, "-frames:v", "1", "-vf", `crop=iw:${y1 - y0}:0:${y0}`, "-q:v", "5", outs[outs.length - 1]); });
        faceTimes.forEach((tt, k) => { outs.push(`${dir}/f${k}.jpg`); args.push("-map", `${bandTimes.length + k}:v:0`, "-frames:v", "1", "-vf", "scale=960:-2", "-q:v", "4", outs[outs.length - 1]); });
        const stateOf = (run: any) => async (id: string) => String((await run(`return (await selects.media.job(${JSON.stringify(id)}).status()).state;`, "Take frames")) || "");
        await runFrameJob({
          start: async () => (await scriptNow(`await selects.files.mkdir(${JSON.stringify(dir)}, { recursive: true }); return await selects.media.startFFmpeg({ args: ${JSON.stringify(args)} });`, "Take frames", true)).jobId,
          state: stateOf(script),
          settled: stateOf(scriptNow),
          cancel: async (id) => { await scriptNow(`await selects.media.job(${JSON.stringify(id)}).cancel();`, "Stop taking frames", true); },
          wait: (ms) => guard(sleep(ms)),
          idle: (ms) => sleep(ms),
          now: () => Date.now(),
          limitMs: 60000,
          stopped: () => !!runRef.current?.cancelled,
          stopError: () => new RunCancelled(),
        });
        const imgs: HTMLImageElement[] = [];
        for (const path of outs) {
          let b64 = "";
          for (let off = 0; off < 8e6; off += SDK_PIECE) {
            const r = await script(`return await selects.files.readRange({ path: ${JSON.stringify(path)}, offset: ${off}, length: ${SDK_PIECE} });`, "Read a frame");
            b64 += r.base64;
            if (r.bytesRead < SDK_PIECE) break;
          }
          const img = new Image();
          img.src = "data:image/jpeg;base64," + b64;
          await img.decode();
          imgs.push(img);
        }
        const sheet = (w: number, h: number) => {
          const cv = document.createElement("canvas");
          cv.width = w;
          cv.height = h;
          const g = cv.getContext("2d") as CanvasRenderingContext2D;
          g.fillStyle = "#ffffff";
          g.fillRect(0, 0, w, h);
          g.fillStyle = "#000000";
          g.font = "bold 22px sans-serif";
          return { cv, g };
        };
        // Sheet 1: stretches (rows) \u00d7 faces (columns), four close-ups per cell.
        const cs = 100, lw = 44, hh = 34, cellW = 4 * cs + 6;
        const s1 = sheet(lw + faces.length * (cellW + 16), hh + chunks.length * (cs + 10));
        faces.forEach((f: any, col: number) => s1.g.fillText(String(col + 1), lw + col * (cellW + 16) + cellW / 2 - 6, 24));
        chunks.forEach((k: any, row: number) => {
          const y = hh + row * (cs + 10);
          s1.g.fillText(String(row + 1), 8, y + cs / 2 + 8);
          faces.forEach((f: any, col: number) => {
            for (let n = 0; n < 4; n++) {
              const img = imgs[row * 4 + n];
              // The face where it was detected nearest that moment (people lean), else where it usually sits.
              const tt = bandTimes[row * 4 + n];
              let lo = 0, hi2 = samples.length - 1;
              while (lo < hi2) { const m = (lo + hi2) >> 1; if (samples[m][0] < tt) lo = m + 1; else hi2 = m; }
              const dd = (q: number[]) => Math.hypot(q[0] - f.x, (q[4] ?? f.cy) - f.cy);
              const near = (samples[lo]?.[1] || []).filter((q: number[]) => dd(q) < f.w * 1.2).sort((p: number[], q: number[]) => dd(p) - dd(q))[0];
              const [fx, fw, , , fy] = near && Math.abs(samples[lo][0] - tt) < 0.6 ? near : [f.x, f.w, 0, 0, f.cy];
              const side = fw * 2.1;
              s1.g.drawImage(img, fx - side / 2, (fy ?? f.cy) - y0 - side / 2, side, side, lw + col * (cellW + 16) + n * (cs + 2), y, cs, cs);
            }
          });
        });
        // Sheet 2: faces (rows, numbered as the columns of sheet 1) \u00d7 close-up alternatives.
        const winH = L.windowBottom - L.windowTop, tw = 280, th = Math.round((tw * winH) / 1080), cols = Math.max(...faces.map((f: any) => f.alts.length));
        const s2 = sheet(lw + cols * (tw + 12), faces.length * (th + 34) + 12);
        const faceY = (Number(L.faceY) || 40) / 100;
        faces.forEach((f: any, row: number) => {
          const y = 12 + row * (th + 34), img = imgs[bandTimes.length + row], k = img.naturalWidth / src.W;
          s2.g.fillText(String(row + 1), 8, y + th / 2);
          f.alts.forEach((alt: number[], col: number) => {
            const [sx, sy, sw, sh] = cropRect({ cx: alt[0], w: alt[1], cy: f.cy }, L, src.W, srcH, faceY, inset);
            const xx = lw + col * (tw + 12);
            s2.g.drawImage(img, sx * k, sy * k, sw * k, sh * k, xx, y, tw, th);
            s2.g.fillText(String.fromCharCode(65 + col), xx + tw / 2 - 7, y + th + 24);
          });
        });
        const prompt =
          `\uc774\ubbf8\uc9c0 \ub450 \uc7a5\uc740 \ubc29\uc1a1 \ud328\ub110 \ud1a0\ub860 \uc601\uc0c1\uc758 \ud55c \ud074\ub9bd\uc774\ub2e4.\n` +
          `\uc774\ubbf8\uc9c0 1: \uac01 \uc904(1-${chunks.length})\uc740 \ud074\ub9bd\uc758 \ud55c \uad6c\uac04\uc774\uace0, \uac01 \uc5f4(1-${faces.length})\uc740 \ud654\uba74 \uc18d \uc0ac\ub78c \ud55c \uba85\uc774\ub2e4. \uce78\ub9c8\ub2e4 \uadf8 \uad6c\uac04\uc5d0\uc11c \uadf8 \uc0ac\ub78c\uc758 \uc5bc\uad74\uc744 \uc2dc\uac04 \uc21c\uc11c\ub85c \ub124 \ubc88 \ucc0d\uc5c8\ub2e4. ` +
          `\uc904\ub9c8\ub2e4 \uadf8 \uad6c\uac04\uc5d0 \ub9d0\ud558\uace0 \uc788\ub294 \uc0ac\ub78c\uc758 \uc5f4 \ubc88\ud638\ub97c \uace8\ub77c\ub77c. \ub124 \uc7a5\uc5d0 \uac78\uccd0 \uc785\uc774 \ubc8c\uc5b4\uc9c0\uace0 \uc785 \ubaa8\uc591\uc774 \uacc4\uc18d \ubc14\ub00c\ub294 \uc0ac\ub78c\uc774 \ub9d0\ud558\ub294 \uc0ac\ub78c\uc774\ub2e4. \uace0\uac1c\ub97c \uc219\uc774\uac70\ub098 \ub044\ub355\uc774\uac70\ub098 \uc6c3\ub294 \uac83\ub9cc\uc73c\ub85c\ub294 \ub9d0\ud558\ub294 \uac83\uc774 \uc544\ub2c8\ub2e4. \uc54c \uc218 \uc5c6\uc73c\uba74 0.\n` +
          `\uc774\ubbf8\uc9c0 2: \uac01 \uc904(1-${faces.length})\uc740 \uc774\ubbf8\uc9c0 1\uc758 \uac19\uc740 \ubc88\ud638 \uc0ac\ub78c\uc744 \uc138\ub85c \ud654\uba74\uc5d0 \ub2f4\ub294 \ud6c4\ubcf4 A-${String.fromCharCode(64 + cols)}\ub2e4. \uc904\ub9c8\ub2e4 \ud558\ub098\ub97c \uace8\ub77c\ub77c. \uae30\uc900\uc744 \uc21c\uc11c\ub300\ub85c \uc801\uc6a9\ud55c\ub2e4: ` +
          `(1) \uadf8 \uc0ac\ub78c\uc758 \uba38\ub9ac\uc640 \uc5b4\uae68\uac00 \uc798\ub9ac\uc9c0 \uc54a\ub294\ub2e4. (2) \ub2e4\ub978 \uc0ac\ub78c\uc758 \uc5bc\uad74, \ubab8, \uc5b4\uae68, \ud314, \uc190\uc774 \uac00\uc7a5\uc790\ub9ac\uc5d0 \uc870\uae08\uc774\ub77c\ub3c4 \ubcf4\uc774\uc9c0 \uc54a\ub294\ub2e4. (3) \uc138\ud2b8 \ubcbd\uc758 \uc774\uc74c\uc0c8, \ud328\ub110 \uacbd\uacc4, \uae30\ub465\ucc98\ub7fc \uac00\uc7a5\uc790\ub9ac\ub97c \uc138\ub85c\ub85c \uc9c0\ub098\ub294 \uc120\uc774 \ubcf4\uc774\uc9c0 \uc54a\ub294\ub2e4. ` +
          `(4) \uc774 \uc870\uac74\uc744 \uc9c0\ud0a4\ub294 \ud6c4\ubcf4 \uc911 \uac00\uc7a5 \ub113\uac8c \ubcf4\uc774\ub294 \uac83. \ubaa8\ub450 \uc5b4\uae0b\ub098\uba74 \uc5b4\uae0b\ub0a8\uc774 \uac00\uc7a5 \uc791\uc740 \uac83.\n` +
          `\ub3c4\uad6c\ub294 \uc4f0\uc9c0 \ub9d0\uace0 \uc774\ubbf8\uc9c0\ub9cc \ubcf4\uace0 \ub2f5\ud558\ub77c. JSON\ub9cc \ub2f5\ud558\ub77c: {"talkers": {"1": 2, "2": 0}, "crops": {"1": "B", "2": "A"}}`;
        // askAI refuses an image over 1,500,000 base64 characters: a big sheet is sent at a lower JPEG quality. Even at
        // the lowest it may stay too big; the host then refuses the call and the first guess stands.
        const quality: number[] = [];
        const encode = (cv: HTMLCanvasElement) => {
          for (const q of [0.85, 0.7, 0.55, 0.4, 0.3]) {
            const d = cv.toDataURL("image/jpeg", q);
            if (d.length < 1.4e6 || q === 0.3) { quality.push(q); return d; }
          }
          return "";
        };
        const r: any = await guard(
          // Asked like the app's other AI asks. A model that cannot read images fails here, and the first guess stands.
          sdk.askAI({
            prompt,
            images: [
              { dataUrl: encode(s1.cv), name: "talkers.jpg" },
              { dataUrl: encode(s2.cv), name: "crops.jpg" },
            ],
            timeoutMs: 75000,
          })
        );
        const ans = extractJson(r.text, S);
        const forced: any[] = [];
        chunks.forEach((k: any, row: number) => {
          const n = Number(ans?.talkers?.[String(row + 1)]);
          if (n >= 1 && n <= faces.length) forced.push({ start: k.start, end: k.end, x: faces[n - 1].x, y: faces[n - 1].cy });
        });
        const crops: any[] = [];
        faces.forEach((f: any, row: number) => {
          const letter = String(ans?.crops?.[String(row + 1)] || "").trim().toUpperCase();
          const alt = f.alts[letter.charCodeAt(0) - 65];
          if (alt) crops.push({ x: f.x, y: f.cy, alt });
        });
        note({
          clip: i,
          plan: "picture",
          seconds: Math.round((Date.now() - t0) / 100) / 10,
          quality,
          chunks: chunks.map((k: any, row: number) => ({ start: Math.round(k.start * 10) / 10, end: Math.round(k.end * 10) / 10, face: k.x, saw: ans?.talkers?.[String(row + 1)] ?? null })),
          faces: faces.map((f: any, row: number) => ({ x: f.x, alts: f.alts, pick: ans?.crops?.[String(row + 1)] ?? null })),
        });
        return { forced, crops };
      } catch (e: any) {
        if (e instanceof RunCancelled) throw e;
        console.warn("[shortform-clips] picture check failed", e);
        note({ clip: i, plan: "picture", error: String(e?.message || e).slice(0, 200), seconds: Math.round((Date.now() - t0) / 100) / 10 });
        return null;
      }
    }

    // Each level is tried only if the one before it failed: the clip's stretch, the same once more (the runtime
    // can crash once), then only the clip's own passages with half the samples.
    const levels = [
      { pad: 30, step: 0.1 },
      { pad: 30, step: 0.1 },
      { pad: 0, step: 0.2 },
    ];
    // Set when a face job's state couldn't be learned: it may still hold the runtime, so no further job is sent
    // in this run and the remaining clips show the whole picture. Its key is in the log for recovery.
    let held = false;
    for (let i = 0; i < clips.length; i++) {
      const c = clips[i];
      if (Array.isArray(c.reframe)) continue;
      let plan: any = null;
      for (let level = 0; level < levels.length && !plan && !held; level++) {
        const ranges = faceRanges(c.segments, Number(src.duration) || Infinity, levels[level].pad);
        if (!ranges.length) break;
        try {
          const got = await findFaces(i, level, ranges, levels[level].step);
          const a = ranges[0][0], b = ranges[ranges.length - 1][1];
          const words = await script(
            res +
              SCRIPT_SOURCE_READER + `const { meta: m, words } = await readClipSource(p, RID); ` +
              `return words.filter((w: any) => !w.nonSpeech && w.endFrame / m.fps >= ${a} && w.startFrame / m.fps <= ${b}).map((w: any) => [Math.round((w.startFrame / m.fps) * 100) / 100, Math.round((w.endFrame / m.fps) * 100) / 100, w.speakerId ?? null, String(w.text || "")]);`,
            "Read speakers"
          );
          const coverW = (got.H * 1080) / Math.max(1, L.windowBottom - L.windowTop);
          if (!got.samples.some((s: any) => s[1]?.length)) continue;
          const sents = sentencesOf(words);
          const replan = (lg: any, forced?: any[]) => planShots(got.samples, speakerTurns(words, a, b), got.W, windowW, Number(L.closeUp) || 4.5, inset, !!L.splitHalves, coverW, Number(L.closeUpMin) || 2.8, lg, sents, forced);
          let log: any = {};
          let shots = replan(log);
          const inClip = (pc: any) => c.segments.some((sg: number[]) => pc.end > sg[0] && pc.start < sg[1]);
          note({ clip: i, level, plan: "faces", voice: log.voice, units: (log.units || []).filter(inClip), pieces: (log.pieces || []).filter(inClip) });
          const seen = log.faces ? await pictureCheck(i, c, log, got.H, got.samples) : null;
          if (seen?.forced.length) {
            log = {};
            shots = replan(log, seen.forced);
            note({ clip: i, level, plan: "seen", units: (log.units || []).filter(inClip), pieces: (log.pieces || []).filter(inClip) });
          }
          if (seen?.crops.length)
            for (const s of shots) {
              if (!s.cy) continue;
              const cr = seen.crops.slice().sort((p: any, q: any) => Math.hypot(p.x - s.cx, p.y - s.cy) - Math.hypot(q.x - s.cx, q.y - s.cy)).find((x: any) => Math.hypot(x.x - s.cx, x.y - s.cy) < 160);
              if (cr) { s.cx = cr.alt[0]; s.w = cr.alt[1]; }
            }
          plan = shots.length ? shots.map(({ alts, ...s }: any) => s) : null;
        } catch (e: any) {
          if (e instanceof RunCancelled) throw e;
          console.warn("[shortform-clips] face finding failed", level, e);
          if (e?.unsettled) held = true;
        }
      }
      if (!plan) {
        // No faces at all: the whole picture, so nobody is cut in half.
        plan = [{ start: 0, end: 1e9, cx: Math.round(src.W / 2), w: Math.round(src.W - 2 * inset) }];
        note({ clip: i, plan: "whole", ...(held ? { held: true } : {}) });
      }
      c.reframe = plan;
      await saveClip();
    }
  }

  // ---- Step 4: recommend a count and choose passages, following the template's instructions ----
  async function choose(tpl: any, title: string, lines: any[], duration: number, cMode: string, cNum: number, cNote: string) {
    const p = tpl.prompt;
    let tx = lines.map((l) => `[${l[0]}-${l[1]}] ${l[2]}`).join("\n");
    let truncated = false;
    if (tx.length > 90000) {
      tx = tx.slice(0, 90000);
      truncated = true;
    }
    const want = cMode === "manual" ? `\uc815\ud655\ud788 ${cNum}\uac1c\ub97c \ub9cc\ub4e0\ub2e4.` : `\uba87 \uac1c\ub97c \ub9cc\ub4e4\uc9c0 \ucd94\ucc9c\ud558\ub77c. ${p.countGuide} \uae30\uc900\uc744 \ub118\ub294 \uad6c\uac04\uc774 \ubd80\uc871\ud558\uba74 \uc801\uac8c \ub9cc\ub4e0\ub2e4. \uc57d\ud55c \ud074\ub9bd\uc73c\ub85c \ucc44\uc6b0\uc9c0 \ub9c8\ub77c.`;
    const prompt = [
      `${p.role} \uc544\ub798 \uc720\ud29c\ube0c \uc6d0\ubcf8(${nameOf(tpl, "ko")}, \uae38\uc774 ${Math.round(duration)}\ucd08)\uc5d0\uc11c \ud2f1\ud1a1\uc6a9 \uc138\ub85c \ud074\ub9bd \uad6c\uac04\uc744 \uace0\ub978\ub2e4.`,
      `\uc81c\ubaa9/\ud30c\uc77c\uba85: ${title}`,
      `\ud504\ub85c\uadf8\ub7a8 \ud615\uc2dd: ${p.format}`,
      `\uc774 \ud504\ub85c\uadf8\ub7a8\uc5d0\uc11c \uc870\ud68c\uc218\uac00 \uc798 \ub098\uc624\ub294 \ud074\ub9bd: ${p.good}`,
      `\uc798 \uc548 \ub098\uc624\ub294 \ud074\ub9bd: ${p.bad}`,
      `\uaddc\uce59: ${p.rules} \uc6d0\ubcf8 \uae30\uc900 \uae38\uc774 ${p.lengthGuide}.`,
      `\ud5e4\ub4dc\ub77c\uc778 \ub450 \uc904: ${p.headline}`,
      want,
      CLIP_SCORE_PROMPT,
      tpl.captions.highlight ? `\uc790\ub9c9 \uac15\uc870: \ud074\ub9bd\ub9c8\ub2e4 \uc790\ub9c9\uc5d0\uc11c \ub178\ub780\uc0c9\uc73c\ub85c \uac15\uc870\ud560 \ud575\uc2ec\uc5b4 3-6\uac1c\ub97c highlights\uc5d0 \ub123\uc5b4\ub77c. \uadf8 \ud074\ub9bd \uad6c\uac04\uc758 \uc804\uc0ac\uc5d0 \uadf8\ub300\ub85c \ub098\uc624\ub294 1-3\uc5b4\uc808 \ud45c\ud604\ub9cc \uc4f4\ub2e4(\uc22b\uc790, \uc885\ubaa9·\uae30\uc5c5\uba85, \ud575\uc2ec \uc8fc\uc7a5). \uc870\uc0ac\ub294 \ube7c\uace0 \uc9e7\uac8c.` : "",
      cNote ? `\uc0ac\uc6a9\uc790 \ucd94\uac00 \uc694\uccad: ${cNote}` : "",
      `\uc804\uc0ac\uc758 \uac01 \uc904\uc740 [\uc2dc\uc791\ucd08-\ub05d\ucd08] \ubb38\uc7a5\uc774\ub2e4. segments\uc758 \uc2dc\uc791\uc740 \uc5b4\ub5a4 \uc904\uc758 \uc2dc\uc791\ucd08, \ub05d\uc740 \uc5b4\ub5a4 \uc904\uc758 \ub05d\ucd08\ub85c \uc815\ud655\ud788 \ub9de\ucd98\ub2e4.` + (truncated ? " \uc804\uc0ac\uac00 \uae38\uc5b4 \ub4b7\ubd80\ubd84\uc774 \uc798\ub838\ub2e4. \ud544\uc694\ud558\uba74 \ud504\ub85c\uc81d\ud2b8 \ub3c4\uad6c\ub85c \uc774 \uc601\uc0c1\uc758 \ub098\uba38\uc9c0 \uc804\uc0ac\ub97c \uc77d\uc5b4\ub3c4 \ub41c\ub2e4." : ""),
      (tpl.renderer === "separate-headlines") ? `\uc790\ub9c9 \uc815\ub9ac(\uc74c\uc131 \ud3b8\uc9d1 \uae08\uc9c0): \ub2e8\uc21c \ub9de\uc7a5\uad6c\uc778 \uc608/\ub124/\uc544\ud558, \uc73c\ud760 \uac19\uc740 \ucd94\uc784\uc0c8\uc640 \uc774\ub140 \uc774 \ub140\uc11d\uc758 \uc774\ub140 \uac19\uc740 \uc2e4\ud328\ud55c \uc2dc\uc791\ub9cc captionOmissions\uc5d0 {"startSeconds":\ud574\ub2f9 \uc804\uc0ac \uc904 \uc2dc\uc791,"endSeconds":\ud574\ub2f9 \uc904 \ub05d,"text":"\uc228\uae38 \uc815\ud655\ud55c \ud55c \ub2e8\uc5b4"}\ub85c \uc801\ub294\ub2e4. \uc758\ubbf8 \uc788\ub294 \ub2f5\ubcc0/\ubd80\uc815/\uac15\uc870 \ubc18\ubcf5/\ub9de\uc2b5\ub2c8\ub2e4/\uadf8\ub807\uc8e0\ub294 \ubcf4\uc874\ud55c\ub2e4. \ubd88\ud655\uc2e4\ud558\uba74 \uc0dd\ub7b5\ud558\uc9c0 \ub9c8\ub77c. \uac01 \ubc94\uc704\ub294 20\ucd08 \uc774\ub0b4, \ud574\ub2f9 \ud1a0\ud070\uc5d0\ub9cc \uc801\uc6a9\ud55c\ub2e4. \uac01 clip\uc5d0 \ub0b4\uc6a9\uc5d0 \ub9de\ub294 \uc9e7\uc740 \ud55c \uc904 description(24\uc790 \uc774\ub0b4)\ub3c4 \ud3ec\ud568\ud55c\ub2e4. \ud654\uba74 \uc218\uce58\uc640 \uc778\uc99d \ubc30\uc9c0\ub294 \uc2e4\uc81c \uc9c0\ud45c\uac00 \uc544\ub2cc \ub370\ubaa8\ub2e4.` : "",
      `\uc790\ub9c9\uc5d0 \uc4f8 \ud45c\uae30 \uad50\uc815\ub3c4 \uc54c\ub824\ub77c: \uc778\uba85·\uc9c0\uba85·\uc22b\uc790\uac00 \uc804\uc0ac\uc5d0\uc11c \ud2c0\ub9b0 \uacbd\uc6b0 fixes\uc5d0 {"from": \uc804\uc0ac \ud45c\uae30, "to": \uc62c\ubc14\ub978 \ud45c\uae30}\ub85c (\uc608: "\ud314\ubc31\ub9cc"→"800\ub9cc"). \ud3b8\uc9d1 \ub3c4\uad6c\ub294 \uc4f0\uc9c0 \ub9c8\ub77c.`,
      `JSON\ub9cc \ub2f5\ud558\ub77c. ${(tpl.renderer === "separate-headlines") ? "\ub8e8\ud2b8\uc5d0 captionOmissions \ubc30\uc5f4, \uac01 clip\uc5d0 description\ub3c4 \ubc18\ub4dc\uc2dc \ud3ec\ud568\ud558\ub77c." : ""} {"recommendedCount": n, "countReason": "\ud55c\ub450 \ubb38\uc7a5", "clips": [{"headline1": "...", "headline2": "...", "segments": [[\uc2dc\uc791\ucd08, \ub05d\ucd08]], "highlights": ["..."], "why": "\ud55c \ubb38\uc7a5"}], "fixes": [{"from": "...", "to": "..."}]}`,
      `\uc804\uc0ac:\n${tx}`,
    ]
      .filter(Boolean)
      .join("\n\n");
    const r: any = await guard(sdk.askAI({ prompt, timeoutMs: 600000 }));
    const j = extractJson(r.text, S);
    let clips = (j.clips || []).filter((c: any) => Array.isArray(c.segments) && c.segments.length);
    clips = clips
      .map((c: any) => ({
        ...c,
        assessment: clipAssessment(c.assessment),
        segments: c.segments
          .map((x: any) => [Math.max(0, Number(x[0])), Math.min(duration, Number(x[1]))])
          .filter((x: any) => x[1] - x[0] > 1)
          .sort((a: any, b: any) => a[0] - b[0]),
      }))
      .filter((c: any) => c.segments.length);
    if (cMode === "manual") clips = clips.slice(0, cNum);
    return { clips, recommendedCount: j.recommendedCount ?? clips.length, countReason: j.countReason || "", fixes: Array.isArray(j.fixes) ? j.fixes : [], captionOmissions: (tpl.renderer === "separate-headlines") && Array.isArray(j.captionOmissions) ? j.captionOmissions : [] };
  }

  async function chooseFieldClips(tpl: any, job: any, lines: any[], duration: number) {
    const selected = await script(resolver(job.resourceId,job.resourceName || "") +
      `if (!res || (${JSON.stringify(!!job.resourceName)} && res.name !== ${JSON.stringify(job.resourceName || "")})) throw new Error("The source video is no longer in this project."); return {resourceId:res.resourceId,resourceName:res.name};`, "Resolve scene search source");
    const maxClips = job.countMode === "manual" ? job.count : 10;
    const prompt = fieldPlanPrompt({
      projectId, ...selected, title: job.title || job.resourceName,
      durationSeconds: duration, outputLanguage: lang, maxClips,
      count: job.countMode === "manual" ? job.count : "Recommend a count up to 10; prefer fewer strong clips.",
      headlineStyle: tpl.prompt.headline, lengthGuide: tpl.prompt.lengthGuide,
      brief: job.note || "", transcript: JSON.stringify(lines).slice(0,90000),
    });
    const response: any = await guard(sdk.askAI({prompt,timeoutMs:600000}));
    return parseFieldPlan(extractJson(response.text,S),duration,maxClips,F.invalid);
  }

  async function run(resume?: any) {
    if(overlayLock.current||busy||packLock.current)return;
    setError("");
    if (!projectId) return setError(S.noProject);
    if (!templates.length) return setError(K.empty);
    if (!resume && contentMode === "field" && !templates.some(t=>t.id === program)) return setError(F.template);
    if (!resume && mode === "youtube" && !/^https?:\/\//.test(url.trim())) return setError(S.needUrl);
    if (!resume && mode === "project" && !pick) return setError(S.needPick);
    resultsRevision.current++;
    setWarn("");
    setBusy(true);
    let rejectStop: (e: any) => void = () => {};
    const stop = new Promise<never>((_, reject) => (rejectStop = reject));
    stop.catch(() => {});
    const token = {
      cancelled: false,
      stop,
      cancel() {
        token.cancelled = true;
        rejectStop(new RunCancelled());
      },
    };
    runRef.current = token;
    let job: any = resume ?? { id: Date.now().toString(36), projectId, created: new Date().toISOString(), mode, contentMode, url: url.trim(), pick, program, countMode, count, note, platform };
    setRunInfo(job);
    let revealedResults = false;
    const persist = async (patch: any) => {
      job = { ...job, ...patch, updated: new Date().toISOString() };
      setRunInfo(job);
      await saveJob(job);
      if (resultProject.current===job.projectId && job.built?.some((d: any)=>d?.draftId || d?.error)) {
        const snapshot=clone(job);
        setResultJobs(rows=>savedDraftResults([...rows.filter(j=>j.id!==snapshot.id),snapshot],job.projectId));
        // Reveal the first usable clip once; later saves must not override the user's navigation.
        if (!revealedResults && snapshot.built.some((d: any)=>d?.draftId)) {
          revealedResults = true;
          setResultSelection(job.id);
          setTab("results");
        }
      }
    };
    try {
      const list = (await loadTemplates()) || templates;
      await persist({});
      setJobs((js) => js.filter((j) => j.id !== job.id));
      setStep(0);
      if (!job.resourceId) {
        if (job.mode === "youtube") {
          const r = await prepareFromYoutube(job.url);
          await persist({ resourceId: r.resourceId, resourceName: r.resourceName, title: r.title });
        } else {
          const nm = resources.find((r) => r.id === job.pick)?.name || "";
          await persist({ resourceId: job.pick, resourceName: nm, title: nm });
        }
      }
      setStep(1);
      setStatus("");
      // Recheck on resume: a saved readiness flag is not evidence the source still exists.
      await ensureTranscriptReady(job.resourceId, job.resourceName || "", fieldMode(job), fieldMode(job) ? F.waiting : S.waitingAnalysis);
      const { lines, duration } = await readTranscript(job.resourceId, job.resourceName || "");
      if (!fieldMode(job) && !lines.length) throw new Error(S.emptyTranscript);
      await persist({ transcriptReady: true });
      setStep(2);
      setStatus(S.identifying);
      if (!job.key) {
        let key = job.program !== "auto" && list.some((t: any) => t.id === job.program) ? job.program : null;
        let why = key ? S.whyManual : "";
        if (!key && fieldMode(job)) throw new Error(F.template);
        if (!key) {
          const id = await identify(job.title || "", lines, list);
          key = id.key;
          why = id.why;
        }
        if (!key) throw new Error(S.unsupported);
        await persist({ key, why });
      }
      const selected = list.find((t: any) => t.id === job.key);
      const tpl = selected?.renderer === "series" ? forPlatform(selected, job.platform ?? "tiktok") : selected;
      if (!tpl) throw new Error(S.templateGone);
      await persist({templateName:nameOf(tpl,lang)});
      setInfo({ key: job.key, why: job.why });
      setStep(3);
      setStatus(fieldMode(job) ? F.choosing : S.choosing);
      if (!job.choice) {
        const pickd = fieldMode(job)
          ? await chooseFieldClips(tpl, job, lines, duration)
          : await choose(tpl, job.title || "", lines, duration, job.countMode, job.count, job.note);
        if (!pickd.clips.length) throw new Error(S.noPassage);
        // Names are fixed here so a resumed job finds the drafts it already made, whatever the app language.
        pickd.clips = pickd.clips.map((c: any, i: number) => ({
          ...c,
          name: `${nameOf(tpl, lang)} ${i + 1} · ${String(c.headline1).replace(/["“”]/g, "").slice(0, 28)} · ${job.id}`,
        }));
        await persist({ choice: pickd });
      }
      const pickd = job.choice;
      setInfo({ key: job.key, why: job.why, recommended: pickd.recommendedCount, countReason: pickd.countReason });
      setStep(4);
      let resultWarning = job.resultWarning || (fieldMode(job) && pickd.searchComplete === false ? F.review : "");
      if (!fieldMode(job) && (tpl.renderer === "series") && tpl.layout.reframe && !pickd.reframed) {
        setStatus(S.reframing);
        const note = (entry: any) => {
          pickd.reframeLog = [...(pickd.reframeLog || []), { at: new Date().toISOString(), ...entry }].slice(-300);
        };
        // Source-read failures stop this run; do not invent a 1920px fallback for unknown media.
        // Face-job failures are recovered inside reframeClips, preserving each completed clip's plan.
        await reframeClips(pickd.clips, job, tpl, note, () => persist({ choice: pickd }));
        pickd.reframed = true;
        if (pickd.reframeLog.some((entry: any) => entry.plan === "whole")) resultWarning = S.reframeSkipped;
        await persist({ choice: pickd, resultWarning });
      }
      if(!fieldMode(job) && tpl.framingMode === "single-speaker") resultWarning = S.singleSpeakerNote;
      if (resultWarning) setWarn(resultWarning);
      const transform = cropTransform(tpl.layout);
      const buildLogo = (tpl.renderer === "separate-headlines") && tpl.logo.mode === "image" ? await compactLogo(tpl.logo.image) : tpl.logo.image;
      const made: any[] = Array.isArray(job.built) ? job.built.slice() : [];
      for (let i = 0; i < pickd.clips.length; i++) {
        const c = pickd.clips[i];
        if (made[i]?.draftId) continue;
        setStatus(S.building(i + 1, pickd.clips.length));
        setSub(i / pickd.clips.length);
        const name = c.name || `${nameOf(tpl, lang)} ${i + 1} · ${String(c.headline1).replace(/["“”]/g, "").slice(0, 28)} · ${job.id}`;
        // A draft committed just before the panel closed is found by its unique name instead of being built twice.
        const found = await script(
          `const m = await selects.project(${JSON.stringify(projectId)}).meta(); for (const id of m.draftIds) { const dm = await selects.draft(id).meta(); if (dm.name === ${JSON.stringify(name)}) return { draftId: id, seconds: Math.round(dm.durationSeconds * 10) / 10 }; } return null;`,
          "Check for an existing draft"
        );
        if (found?.draftId) {
          made[i] = { ...c, name, draftId: found.draftId, seconds: found.seconds };
        } else {
          const P = {
            projectId,
            resourceId: job.resourceId,
            resourceName: job.resourceName || "",
            name,
            segments: c.segments,
            transform,
            ...((tpl.renderer === "series")
              ? splitDate(withEpisodeDate(radioFrameParams(tpl, c.headline1, c.headline2), tpl, job.title || ""), S)
              : {frame: frameParams(tpl, c.headline1, c.headline2, {logo: buildLogo})}),
            separateHeadlines: !!(tpl.renderer === "separate-headlines"), demoOverlay: false, overlayResourceId: null,
            captionOmissions: pickd.captionOmissions || [],
            editableFrame: (tpl.renderer === "series") ? radioEditableFrame(S) : editableFrame(S),
            caption: tpl.captions.on ? ((tpl.renderer === "series") ? radioCaptionParams(tpl) : captionParams(tpl)) : null,
            editableCaption: editableCaption(S),
            captions: !!tpl.captions.on,
            ...fieldBuildOptions(job,tpl),
            lineMax: tpl.captions.lineMax || 16,
            highlights: tpl.captions.highlight && Array.isArray(c.highlights) ? c.highlights : [],
            reframeInset: Number(tpl.layout.edgeInset) || 0,
            reframeFaceY: (Number(tpl.layout.faceY) || 40) / 100,
            reframe: fieldMode(job) ? null : c.reframe || null,
            fixes: pickd.fixes,
          };
          try {
            const buildScript = (tpl.renderer === "series") ? RADIO_SCRIPT_BUILD : SCRIPT_BUILD;
            const code = buildScript.replace("const P: any = __P__;", "const P: any = " + JSON.stringify(P) + ";");
            if (code.length > SCRIPT_LIMIT) throw new Error(S.imagesTooLarge);
            let r: any;
            try {
              r = await script(code, `Build ${name}`, true);
            } catch (e: any) {
              if (e instanceof RunCancelled || !(tpl.renderer === "series") || !P.removeSilences || !/owning Main placement/.test(String(e?.message || e))) throw e;
              P.removeSilences = false;
              r = await script(buildScript.replace("const P: any = __P__;", "const P: any = " + JSON.stringify(P) + ";"), `Build ${name}`, true);
            }
            made[i] = { ...c, name, draftId: r?.draftId, seconds: r?.seconds };
          } catch (e: any) {
            if (e instanceof RunCancelled) throw e;
            made[i] = { ...c, name, error: String(e?.message || e).slice(0, 300) };
          }
        }
        setDrafts(made.filter(Boolean));
        await persist({ built: made, resultWarning });
        if (made[i]?.draftId) {
          try {
            const image = await guard(loadDraftThumbnail(store,sdk,projectId,job.id,made[i].draftId));
            if (image?.thumbnailPath) {
              made[i] = {...made[i],thumbnailPath:image.thumbnailPath,thumbnailCapturedAt:new Date().toISOString()};
              await persist({built:made,resultWarning});
            }
          } catch (e) { if (e instanceof RunCancelled) throw e; /* A preview failure leaves the editable clip intact. */ }
        }
      }
      const allBuilt = made.length === pickd.clips.length && made.every((m) => m && m.draftId);
      await persist({ done: allBuilt });
      setStatus(S.done(made.filter((m) => m && m.draftId).length));
      if (!allBuilt) setError(made.filter((m) => m && m.error).map((m) => m.error).join(" / ").slice(0, 600) + " " + S.resumeHint);
      setStep(5);
      loadResources();
    } catch (e: any) {
      if (e instanceof RunCancelled) {
        setError("");
        setStatus(S.cancelled);
      } else {
        setError(String(e?.message || e) + " " + S.resumeHint);
      }
      loadJobs();
    } finally {
      if (runRef.current === token) runRef.current = null;
      setBusy(false);
      setCancelling(false);
    }
  }

  function cancelRun() {
    if (!runRef.current || runRef.current.cancelled) return;
    setCancelling(true);
    runRef.current.cancel();
  }

  async function dismissJob(job: any) {
    await saveJob({ ...job, dismissed: true, updated: new Date().toISOString() });
    loadJobs();
  }

  async function openDraft(id: string) {
    if (openingLock.current) return;
    openingLock.current = true;
    setOpeningDraft(id);
    try {
      await script(`return await selects.editor.openDraft(${JSON.stringify(id)});`, "Open the draft");
      setOverlayRefresh(n => n + 1);
    } catch (e: any) {
      setError(String(e?.message || e));
    } finally {
      openingLock.current = false;
      setOpeningDraft(null);
    }
  }

  const programOptions = [...(contentMode === "field" ? [] : [{ value: "auto", label: S.auto }]), ...templates.map((t) => ({ value: t.id, label: nameOf(t, lang) }))];
  const videoOptions = resources.map((r) => {
    const duration = r.sec > 0 ? (r.sec < 60 ? S.seconds(r.sec) : S.minutes(Math.floor(r.sec / 60))) : "";
    return {value:r.id,label: `${r.name}${duration ? " · " + duration : ""}${r.transcribed || r.analyzed ? "" : " · " + S.notAnalyzed}`};
  });
  const history=savedDraftResults(resultJobs,projectId || "");
  const shownResult=(resultSelection === "__latest__" ? history[0] : history.find(j=>j.id===resultSelection)) || history[0];
  const shownDrafts=shownResult?.built?.filter(Boolean) || [];
  const shownTemplate=templates.find(t=>t.id===shownResult?.key);
  const infoTpl = info ? templates.find((t) => t.id === info.key) : null;
  const resourceName = (id: string | null) => resources.find((r) => r.id === id)?.name || "";
  const templateName = (id: string) => {
    const t = templates.find((x) => x.id === id);
    return t ? nameOf(t, lang) : "";
  };

  const sourceAction =
    mode === "project" ? <ui.IconButton icon="refresh" label={S.refresh} onClick={loadResources} disabled={busy} /> : undefined;

  // While a run is going the form is locked anyway, so it folds into what is being made and the progress
  // stays in view.
  const runSummary = runInfo && (
    <ui.Section title={S.thisRun}>
      <div style={{ ...CARD, ...FORM_COLUMN }}>
        <ui.Stack gap={4}>
          <strong style={CLAMP2}>
            {runInfo.mode === "youtube" ? runInfo.title || runInfo.url : runInfo.resourceName || resourceName(runInfo.pick)}
          </strong>
          <small>
            {[
              runInfo.key ? templateName(runInfo.key) : runInfo.program === "auto" ? S.auto : templateName(runInfo.program),
              runInfo.countMode === "manual" ? S.clipsUnit(runInfo.count) : S.countAuto,
              fieldMode(runInfo) ? F.field : null,
            ]
              .filter(Boolean)
              .join(" · ")}
          </small>
          {runInfo.note ? <small style={CLAMP2}>{runInfo.note}</small> : null}
        </ui.Stack>
      </div>
    </ui.Section>
  );

  const countOptions = [
    { value: "auto", label: S.countAuto },
    ...Array.from({ length: 10 }, (_, i) => ({ value: String(i + 1), label: S.clipsUnit(i + 1) })),
  ];

  const form = (
    <div style={{width:"100%",maxWidth:"var(--panel-field-max, 480px)",marginInline:"auto",minWidth:0,paddingBlock:8}}>
      <ui.Stack gap={8}>
        <ui.Stack gap={4}>
          <h3 style={{margin:0,minHeight:0,fontSize:12,fontWeight:400,lineHeight:"16px",color:"var(--panel-muted-fg)"}}>{S.source}</h3>
          <ui.Stack gap={8}>
          <ui.Segmented
            label={S.sourceKind}
            value={mode}
            onChange={setMode}
            options={[
              { value: "youtube", label: S.fromYoutube },
              { value: "project", label: S.fromProject },
            ]}
          />
          {mode === "youtube" ? (
            <ui.TextField value={url} onChange={setUrl} placeholder={S.urlPh} />
          ) : (
            <div style={{display:"flex",alignItems:"center",gap:8,minWidth:0}}>
              <div style={{flex:1,minWidth:0}}>
                <ui.Select label={S.pick} value={pick} onChange={setPick} options={videoOptions} placeholder={S.pickPh} />
              </div>
              {sourceAction}
            </div>
          )}
          </ui.Stack>
        </ui.Stack>
        <ui.Stack gap={4}>
          <h3 style={{margin:0,minHeight:0,fontSize:12,fontWeight:400,lineHeight:"16px",color:"var(--panel-muted-fg)"}}>{S.optionsSec}</h3>
          <ui.Stack gap={8}>
        <ui.Segmented label={F.label} value={contentMode} onChange={setContentMode}
          options={[{value:"speech",label:F.speech},{value:"field",label:F.field}]} />
        {contentMode === "field" && <small>{F.hint}</small>}
        <ui.Select label={S.programPick} value={contentMode === "field" && program === "auto" ? null : program} onChange={setProgram} options={programOptions} placeholder={contentMode === "field" ? F.template : undefined} />
        {(program === "auto" || templates.find(t => t.id === program)?.renderer === "series") && <ui.Segmented
          label={S.layoutKind} value={platform} onChange={setPlatform}
          options={[{value: "tiktok", label: S.layoutTiktok}, {value: "shorts", label: S.layoutShorts}]}
        />}
        <ui.Select
          label={S.count}
          value={countMode === "manual" ? String(count) : "auto"}
          onChange={(v: string) => {
            if (v === "auto") return setCountMode("auto");
            setCountMode("manual");
            setCount(Number(v));
          }}
          options={countOptions}
        />
        <ui.TextField label={S.note} value={note} onChange={setNote} placeholder={S.notePh} />
          </ui.Stack>
        </ui.Stack>
      </ui.Stack>
    </div>
  );

  const steps = fieldMode(runInfo) ? F.steps : S.steps;
  const elapsed = Math.max(0, Math.floor((now - stepStarted.current) / 1000));
  const statusLine = busy && step >= 0 ? [status, S.elapsed(elapsed)].filter(Boolean).join(" · ") : status;

  const make = templatesLoading ? <ui.Message>{K.loading}</ui.Message> : !templates.length ? <ui.Stack gap={8}><ui.Message>{K.empty}</ui.Message>{packError && <ui.Message tone="error">{packError}</ui.Message>}<ui.Button variant="secondary" onClick={()=>setTab("templates")}>{S.tabTemplates}</ui.Button></ui.Stack> : !projectId ? (
    <ui.Message>{S.noProject}</ui.Message>
  ) : (
    <>
      {jobs.length > 0 && !busy && (
        <ui.Section title={S.saved}>
          {jobs.slice(0, 3).map((j) => (
            <div key={j.id} style={CARD}>
              <ui.Stack gap={4}>
                <strong style={CLAMP2}>{(j.title || j.url || resourceName(j.pick) || "").slice(0, 80)}</strong>
                <small>{S.stage(j)}</small>
                <ui.Row gap={8}>
                  <ui.Button variant="secondary" onClick={() => run(j)}>
                    {S.resume}
                  </ui.Button>
                  <ui.Button variant="ghost" onClick={() => dismissJob(j)}>
                    {S.dismiss}
                  </ui.Button>
                </ui.Row>
              </ui.Stack>
            </div>
          ))}
        </ui.Section>
      )}
      {busy ? runSummary : form}
      <ui.Stack gap={8}>
        <ui.Actions>
          {busy && (
            <ui.Button variant="secondary" onClick={cancelRun} disabled={cancelling}>
              {cancelling ? S.cancelling : S.cancel}
            </ui.Button>
          )}
          <ui.Button variant="primary" busy={busy} disabled={overlayBusy || packBusy || templatesLoading || !templates.length} busyLabel={S.making} onClick={() => run()}>
            {S.make}
          </ui.Button>
        </ui.Actions>
        {step >= 0 && step < 5 && (
          <ui.Progress
            value={step >= steps.length ? 1 : (step + sub) / steps.length}
            label={step >= steps.length ? S.finished : `${steps[step]} · ${step + 1}/${steps.length}`}
          />
        )}
        {statusLine && (busy || step < 5) && <ui.Message tone={step >= 5 && !busy ? "success" : "muted"}>{statusLine}</ui.Message>}
        {info && drafts.length === 0 && (
          <ui.Message>
            {S.detected}: {infoTpl ? nameOf(infoTpl, lang) : info.key}
            {info.why ? ` · ${firstSentence(info.why)}` : ""}
          </ui.Message>
        )}
        {info && drafts.length === 0 && info.recommended != null && (
          <ui.Message>
            {S.recommended}: {S.clipsUnit(info.recommended)}
            {info.countReason ? ` · ${firstSentence(info.countReason)}` : ""}
          </ui.Message>
        )}
        {warn && drafts.length === 0 && <ui.Message>{warn}</ui.Message>}
        {error && <ui.Message tone="error">{error}</ui.Message>}
      </ui.Stack>


    </>
  );

  const myClips = (
      <div ref={resultsRef} style={FORM_COLUMN}>
      {runInfo?.projectId === projectId && <ClipRunProgress ui={ui} S={S} R={R} job={runInfo} busy={busy}
        step={step} sub={sub} statusLine={statusLine} cancelling={cancelling} onCancel={cancelRun} />}
      {!busy && runInfo?.id === shownResult?.id && step >= 0 && step < 5 && (error || status) &&
        <div style={{marginBottom:16}}><ui.Message tone={error ? "error" : "muted"}>{error || status}</ui.Message></div>}
      {shownDrafts.length > 0 ? <>
        <div style={{marginBottom:16}}><ui.Select label={R.history}
          value={resultSelection === "__latest__" || resultSelection===history[0]?.id || !history.some(j=>j.id===resultSelection) ? "__latest__" : resultSelection}
          onChange={setResultSelection}
          options={[{value:"__latest__",label:`${R.latest} · ${resultJobLabel(history[0],lang,R)}`},
            ...history.slice(1).map(j=>({value:j.id,label:resultJobLabel(j,lang,R)}))]} /></div>
        <DraftResults drafts={shownDrafts} template={shownResult.templateName || (shownTemplate ? nameOf(shownTemplate,lang) : "")}
          sdk={sdk} store={store} jobId={shownResult.id} projectId={projectId} visibleDraftId={visibleDraftId} opening={openingDraft} onOpen={openDraft}
          overlayControl={<ui.Stack gap={4}><ui.Toggle
            label={O.title}
            value={overlayPending ?? !!overlayTarget?.count}
            onChange={(enabled: boolean)=>manageOverlay(enabled?"add":"remove")}
            disabled={busy||overlayBusy||overlayLoading||!overlayTarget}
          />
            {(overlayPending ?? !!overlayTarget?.count)&&<small style={{color:"var(--panel-danger)",fontSize:12,lineHeight:1.5}}>{O.uploadWarning}</small>}
          </ui.Stack>}
          overlayFeedback={<>
            {overlayTarget && !shownDrafts.some((d:any)=>d.draftId===overlayTarget.id) && <small>{R.target}: {overlayTarget.name}</small>}
            {!overlayTarget&&!overlayBusy&&!overlayLoading&&!overlayError&&<ui.Message>{O.empty}</ui.Message>}
            {overlayError&&overlayMessage&&<>
              <ui.Message tone="error">{overlayMessage}</ui.Message>
              <ui.Actions><ui.IconButton icon="refresh" label={O.refresh} onClick={()=>setOverlayRefresh(n=>n+1)} disabled={busy||overlayBusy||overlayLoading||!projectId} /></ui.Actions>
            </>}
          </>}
          ui={ui} S={S} R={R} />
      </> : <ui.Message>{R.emptyClips}</ui.Message>}
      </div>
  );

  return (
    <div style={{ paddingTop: 16, paddingBottom: 16 }}>
    <ui.Tabs
      value={tab}
      onChange={setTab}
      tabs={[
        { value: "make", label: S.tabMake, content: make },
        { value: "results", label: R.myClips, content: myClips },
        {
          value: "templates",
          label: S.tabTemplates,
          content: (
            <>
            {!templates.length && <ui.Actions><ui.Button variant="secondary"
              disabled={busy || packBusy || templatesLoading}
              onClick={()=>{setPackError("");setPackMessage("");setPackDialogOpen(true);}}>{K.title}</ui.Button></ui.Actions>}
            {packMessage && <ui.Message tone="success">{packMessage}</ui.Message>}
            <TemplatePackDialog ui={ui} open={packDialogOpen} title={K.title} closeLabel={S.cancel}
              busy={packBusy} onClose={()=>setPackDialogOpen(false)}>
              <ui.TextField label={K.link} value={packLink} onChange={setPackLink} placeholder={K.linkPlaceholder} disabled={!files || busy || packBusy || templateDirty || templateSaving} />
              <div style={{display:"flex",justifyContent:"flex-end",gap:8,flexWrap:"wrap",paddingTop:4}}><div><ui.Button variant="secondary" disabled={packBusy} onClick={()=>setPackDialogOpen(false)}>{S.cancel}</ui.Button></div><div><ui.Button variant="primary" busy={packBusy} disabled={!files || !packLink.trim() || busy || packBusy || templateDirty || templateSaving} onClick={()=>void installPack()}>{K.installLink}</ui.Button></div></div>
              {!files && <ui.Message tone="error">{K.noFiles}</ui.Message>}
              {templateDirty && <ui.Message>{K.blocked}</ui.Message>}
              {packBusy && <ui.Progress label={K.add} />}
              {packError && <ui.Message tone="error">{packError}</ui.Message>}
            </TemplatePackDialog>
            {templates.length > 0 && <TemplateEditor
              platform={platform}
              packBusy={packBusy}
              busy={busy}
              onAddTemplates={()=>{setPackError("");setPackMessage("");setPackDialogOpen(true);}}
              addTemplatesLabel={K.title}
              ui={ui}
              S={S}
              lang={lang}
              templates={templates}
              store={repository}
              onSavingChange={setTemplateSaving}
              state={{ selId: tplSel, setSelId: setTplSel, edit: tplEdit, setEdit: setTplEdit, baseKey: tplBase, setBaseKey: setTplBase, sub: tplSub, setSub: setTplSub }}
              onChanged={async (id: string) => {
                await loadTemplates();
                return id;
              }}
            />}
            </>
          ),
        },
      ]}
    />
    </div>
  );
}
